import json
from plotly.offline import get_plotlyjs

def build_dashboard(d,out):
    cols=['ma_sach','ngay_ban','kenh_ban','the_loai','gia_ban','so_luong','doanh_thu','diem_danh_gia']
    data=d[cols].to_json(orient='records',force_ascii=False)
    page='''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bán sách | Nghiên cứu mô phỏng</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f1f5f7;color:#14364c;font:16px Arial,sans-serif}main{max-width:1280px;margin:auto;padding:32px}h1{font-size:30px}p{line-height:1.6}.tag{color:#946021;font-weight:bold}.controls{display:flex;gap:18px;flex-wrap:wrap}select{padding:10px;margin:8px;border:1px solid #bacbd4;border-radius:6px}.kpis,.plots{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin-top:22px}.card,.plot{background:white;padding:20px;border:1px solid #dce5ea;border-radius:12px}.card b{display:block;font-size:27px;margin-top:8px}.plot{min-height:370px;padding:0;min-width:0;overflow:hidden}footer{font-size:13px;color:#536879;margin-top:20px}@media(max-width:760px){main{padding:15px}.plots,.kpis{grid-template-columns:1fr}}</style>
<main><p class="tag">NHẬP MÔN KHOA HỌC DỮ LIỆU · DỮ LIỆU MÔ PHỎNG</p><h1>Phân tích bán sách trong một kịch bản giả lập</h1><p>2024–2025 · seed 42 · Chỉ mô tả dữ liệu mô phỏng. Tên sách và kênh không đại diện doanh nghiệp thật. Chọn năm và kênh để cập nhật tất cả chỉ số và biểu đồ.</p>
<div class="controls"><label>Năm<select id="year"><option value="all">Cả hai năm</option><option>2024</option><option>2025</option></select></label><label>Kênh<select id="channel"><option value="all">Tất cả kênh</option></select></label></div>
<div class="kpis"><div class="card">Giá trị bán hàng sau giảm giá<b id="rev"></b></div><div class="card">Số cuốn bán<b id="qty"></b></div><div class="card">Số dòng / đơn một đầu sách<b id="count"></b></div><div class="card">Giá bình quân gia quyền theo số cuốn<b id="avg"></b></div></div>
<div class="plots"><div class="plot" id="timeline"></div><div class="plot" id="genre"></div><div class="plot" id="channels"></div><div class="plot" id="books"></div></div>
<footer>Giá trị bán hàng = giá bán × số cuốn; chưa trừ hoàn/hủy, phí hoặc chi phí. Các tỷ trọng chỉ thuộc tập đang lọc. Kênh vắng dữ liệu không có nghĩa doanh số thực bằng 0. Dashboard hoạt động ngoại tuyến; không gửi dữ liệu ra ngoài.</footer></main><script>__PLOTLY__</script><script>
const rows=__DATA__;const fmt=new Intl.NumberFormat('vi-VN');
for(const c of [...new Set(rows.map(r=>r.kenh_ban))].sort()){let o=document.createElement('option');o.textContent=c;document.getElementById('channel').appendChild(o)}
function agg(rs,key){let m={};for(const r of rs)m[r[key]]=(m[r[key]]||0)+r.doanh_thu;return Object.entries(m)}
function plot(id,title,entries,horizontal=false){let layout={title:{text:title,font:{size:16}},margin:{l:horizontal?155:65,r:18,t:65,b:75},paper_bgcolor:'white',plot_bgcolor:'white',font:{family:'Arial'},xaxis:{title:{text:horizontal?'Triệu đồng':''},type:horizontal?'linear':'category',nticks:8},yaxis:{title:{text:horizontal?'':'Triệu đồng'}},autosize:true};let tr={type:'bar',marker:{color:'#175C80'},x:entries.map(x=>horizontal?x[1]/1e6:x[0]),y:entries.map(x=>horizontal?x[0]:x[1]/1e6),orientation:horizontal?'h':'v'};Plotly.react(id,[tr],layout,{responsive:true,displaylogo:false})}
function update(){let year=document.getElementById('year').value,channel=document.getElementById('channel').value;let rs=rows.filter(r=>(year==='all'||r.ngay_ban.slice(0,4)===year)&&(channel==='all'||r.kenh_ban===channel));let rev=rs.reduce((s,r)=>s+r.doanh_thu,0),qty=rs.reduce((s,r)=>s+r.so_luong,0);document.getElementById('rev').textContent=fmt.format(rev)+' đ';document.getElementById('qty').textContent=fmt.format(qty);document.getElementById('count').textContent=fmt.format(rs.length);document.getElementById('avg').textContent=qty?fmt.format(Math.round(rev/qty))+' đ':'Không có dữ liệu';let monthly=rs.map(r=>({...r,month:r.ngay_ban.slice(0,7)}));plot('timeline','Giá trị bán hàng theo tháng',agg(monthly,'month').sort());plot('genre','Theo thể loại',agg(rs,'the_loai').sort((a,b)=>a[1]-b[1]),true);plot('channels','Theo kênh giả lập',agg(rs,'kenh_ban').sort((a,b)=>a[1]-b[1]),true);plot('books','Top 10 mã sách theo giá trị bán hàng',agg(rs,'ma_sach').sort((a,b)=>b[1]-a[1]).slice(0,10).reverse(),true)}
document.getElementById('year').addEventListener('change',update);document.getElementById('channel').addEventListener('change',update);update();</script></html>'''
    # newline='\n' so the committed dashboard is byte-identical across platforms (F-13).
    out.write_text(page.replace('__PLOTLY__',get_plotlyjs()).replace('__DATA__',data),encoding='utf8',newline='\n')


